<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import {X} from 'lucide-vue-next';
import SelectionToolbar from './SelectionToolbar.vue';
import {selectIds,toggleId,selectionCounts} from './selection';
const props=defineProps<{page:string;active:boolean}>();
const emit=defineEmits<{navigate:[path:string];uploaded:[];workflow:[ids:string[]]}>();
const editOpen=ref(false),historyPreview=ref<any>(null),pageNumber=ref(1);
let anchor:string|null=null,loaded=false,polling=false;
const state=ref<any>(null),error=ref(''),busy=ref(false),authUrl=ref(''),search=ref(''),privacyFilter=ref(''),groupFilter=ref('');
const videos=ref(new Set<string>()),artifacts=ref(new Set<string>()),preview=ref<any>(null);
const edit=ref({find:'',replace:'',regex:false,prefix:'',description:'',tags:'',privacy:'',group:''});
const useWorkflowMetadata=ref(false);
const workflowMetadata=ref<any[]>([]);
const changeDescription=ref(false),changeTags=ref(false),changeGroup=ref(false);
const upload=ref({title:'{文件名}',description:'',tags:'',privacy:'private',category_id:'22',made_for_kids:'no'});
let timer:ReturnType<typeof setInterval>|undefined;
async function api(path:string,body?:any){const r=await fetch('/api/youtube'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const v=await r.json();if(!r.ok)throw Error(v.error??'请求失败');return v;}
async function load(){state.value=await api('');loaded=true;if(props.page==='upload'){const response=await fetch('/api/workflows');if(!response.ok)throw Error('无法读取管线准备资料');workflowMetadata.value=(await response.json()).metadata??[];}}
function prepared(a:any){const sourceIds:string[]=a.source_ids??[];const fields=sourceIds.map(id=>workflowMetadata.value.find(m=>m.kind==='local'&&m.id===id)?.fields);return fields.length&&fields.every(f=>f&&JSON.stringify(f)===JSON.stringify(fields[0]))?fields[0]:null;}
const preparedUploadsValid=computed(()=>[...artifacts.value].every(id=>{const a=available.value.find((a:any)=>a.output_id===id);return a&&prepared(a);}));
async function status(){if(polling||busy.value||!props.active)return;polling=true;try{const value=await api('/status');if(state.value?.channel?.id!==value.channel?.id)loaded=false;state.value={videos:[],artifacts:[],batches:[],...state.value,...value};error.value='';}catch(e){error.value=(e as Error).message;}finally{polling=false;}}
async function activate(){if(!props.active)return;if(props.page==='account')await status();else if(!loaded||props.page==='upload')await run(load);}
async function run(f:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await f();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function config(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f)await run(async()=>{await api('/config',JSON.parse(await f.text()));await load();});(e.target as HTMLInputElement).value='';}
function toggle(which:string,id:string){const set=which==='videos'?videos:artifacts;const n=new Set(set.value);n.has(id)?n.delete(id):n.add(id);set.value=n;}
const filtered=computed(()=> (state.value?.videos??[]).filter((v:any)=>(!search.value||`${v.snippet.title} ${v.id}`.toLowerCase().includes(search.value.toLowerCase()))&&(!privacyFilter.value||v.status.privacyStatus===privacyFilter.value)&&(!groupFilter.value||v.local_group===groupFilter.value)));
const groups=computed(()=>[...new Set<string>((state.value?.videos??[]).map((v:any)=>v.local_group).filter(Boolean))]);
const available=computed(()=>(state.value?.artifacts??[]).filter((a:any)=>!(state.value?.uploads??[]).some((j:any)=>j.artifact_id===a.output_id&&j.channel_id===state.value?.channel?.id)));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/30)));
const currentPage=computed(()=>Math.min(pageNumber.value,pages.value));
const visible=computed(()=>filtered.value.slice((currentPage.value-1)*30,currentPage.value*30));
const selection=computed(()=>selectionCounts(videos.value,filtered.value.map((v:any)=>v.id),visible.value.map((v:any)=>v.id)));
const enabled=computed(()=>state.value?.enabled!==false);
const headings:Record<string,string>={account:'YouTube 账号',upload:'上传准备',videos:'频道视频',history:'批量变更记录'};
function toggleVideo(id:string,event:MouseEvent){videos.value=toggleId(videos.value,id,filtered.value.map((v:any)=>v.id),anchor,event.shiftKey);anchor=id;}
function selectAll(){videos.value=selectIds(videos.value,filtered.value.map((v:any)=>v.id),'add');}
function selectPage(){videos.value=selectIds(videos.value,visible.value.map((v:any)=>v.id),'add');}
function invertResults(){videos.value=selectIds(videos.value,filtered.value.map((v:any)=>v.id),'invert');}
function clearSelection(){videos.value=new Set();anchor=null;editOpen.value=false;preview.value=null;}
function onKeydown(event:KeyboardEvent){if(!props.active||event.key!=='Escape'||event.isComposing||(event.target as HTMLElement).closest('input,textarea,select,[contenteditable="true"]'))return;if(editOpen.value||historyPreview.value){editOpen.value=false;historyPreview.value=null;}else if(props.page==='videos')clearSelection();}
function splitTags(t:string){return t.split(/[,，]/).map(t=>t.trim()).filter(Boolean);}
function makePreview(){run(async()=>{preview.value=await api('/batches/preview',{ids:[...videos.value],find:edit.value.find,replace:edit.value.replace,regex:edit.value.regex,prefix:edit.value.prefix,description:changeDescription.value?edit.value.description:null,tags:changeTags.value?splitTags(edit.value.tags):null,privacy:edit.value.privacy||null,group:changeGroup.value?edit.value.group:null});});}
watch([edit,changeDescription,changeTags,changeGroup,videos],()=>preview.value=null,{deep:true});
watch([search,privacyFilter,groupFilter],()=>pageNumber.value=1);
watch(()=>[props.active,props.page],()=>{editOpen.value=false;historyPreview.value=null;activate();});
onMounted(()=>{activate();timer=setInterval(status,5000);window.addEventListener('keydown',onKeydown);});
onUnmounted(()=>{clearInterval(timer);window.removeEventListener('keydown',onKeydown);});
const labels:Record<string,string>={queued:'排队中',running:'上传中',paused:'已暂停',interrupted:'已中断',failed:'失败',completed:'已完成',pending:'待应用',private:'私密',unlisted:'不公开',public:'公开'};

</script>
<template>
<div class="youtube-workspace">
<div class="page-heading"><div><div class="eyebrow">YOUTUBE WORKSPACE</div><h1>{{headings[page]??'频道视频'}}<span class="heading-dot">.</span></h1><p>{{page==='upload'?'选择成品并提交上传，进度统一显示在任务中心。':page==='account'?'配置与授权保存在本机系统凭据存储中。':page==='history'?'查看已生成的批量操作及逐项执行结果。':'搜索与分组，跨页选择，预览后批量修改。'}}</p></div><button class="subtle" :disabled="busy" @click="run(load)">刷新状态</button></div>
<div v-if="error" class="warning-panel" role="alert">{{error}}</div>
<template v-if="state">
<div v-if="!enabled" class="warning-panel">{{state.reason}}</div>
<div v-if="state.credential_error" class="warning-panel" role="alert">{{state.credential_error}}</div>
<div v-if="page!=='account'&&!state.connected&&enabled" class="info-note">尚未连接频道。<button class="text-action" @click="$emit('navigate','/settings/connections')">前往 YouTube 账号</button></div>
<section v-if="page==='account'" class="panel yt-section"><div class="yt-row"><h2>{{state.connected?'已连接：'+(state.channel?.snippet?.title??'频道'):'连接你的 YouTube 频道'}}</h2><span class="badge" :class="state.connected?'green':'neutral'">{{state.connected?'已授权':state.configured?'配置已保存':'需要 OAuth 配置'}}</span></div><p>在 Google Cloud 启用 YouTube Data API v3，创建「桌面应用」OAuth 客户端，导入下载的 JSON。授权信息保存在系统凭据存储中。</p><div class="yt-row"><label class="subtle">导入 OAuth JSON<input type="file" accept=".json" :disabled="busy||!enabled" @change="config"/></label><button class="primary" :disabled="busy||!enabled||!state.configured" @click="run(async()=>{authUrl=(await api('/connect',{})).url;})">打开系统浏览器授权</button><a v-if="authUrl" :href="authUrl" target="_blank" rel="noreferrer" class="subtle">备用授权链接 ↗</a><button v-if="state.connected" class="subtle" :disabled="busy" @click="run(async()=>{await api('/disconnect',{});authUrl='';await load();})">断开并撤销授权</button></div><p class="muted">授权后回到此页即可。未通过 YouTube 审核的 API 项目可能被限制为私密上传。</p></section>
<section v-if="page==='upload'" class="panel yt-section"><div class="yt-row"><h2>上传管线</h2><span class="muted">合并 / 切割成品 → 串行上传队列 → YouTube 处理</span></div><p v-if="!available.length">暂无待上传成品。先在后处理管线执行合并或自动切割。</p><div class="yt-scroll"><label v-for="a in available" :key="a.output_id" class="checkbox-label"><input type="checkbox" :checked="artifacts.has(a.output_id)" @change="toggle('artifacts',a.output_id)"/><span>{{a.path.split(/[\\/]/).pop()}} · {{(a.bytes/1048576).toFixed(1)}} MiB<small v-if="useWorkflowMetadata" class="block">{{prepared(a)?'管线标题：'+prepared(a).title+' · 实际可见性：'+labels[prepared(a).privacy]:'尚未准备，或来源元信息不一致'}}</small></span></label></div><label class="checkbox-label"><input type="checkbox" v-model="useWorkflowMetadata"/>使用自定义管线准备的源素材元信息（同一成品的所有来源必须已准备且一致）</label><div class="yt-form" :class="{'workflow-inherited':useWorkflowMetadata}"><label class="field-label">标题模板（支持 {文件名}）<input v-model="upload.title" :disabled="useWorkflowMetadata"/></label><label class="field-label">公开状态<select v-model="upload.privacy" :disabled="useWorkflowMetadata"><option value="private">私密</option><option value="unlisted">不公开</option><option value="public">公开</option></select></label><label class="field-label">标签（逗号分隔）<input v-model="upload.tags" :disabled="useWorkflowMetadata"/></label><label class="field-label">分类 ID<input v-model="upload.category_id" :disabled="useWorkflowMetadata"/></label><label class="field-label">是否专为儿童制作<select v-model="upload.made_for_kids"><option value="no">否</option><option value="yes">是</option></select></label></div><label class="field-label">描述<textarea v-model="upload.description" :disabled="useWorkflowMetadata" rows="3"/></label><button class="primary" :disabled="busy||!state.connected||!artifacts.size||(useWorkflowMetadata&&!preparedUploadsValid)" @click="run(async()=>{await api('/uploads',{artifact_ids:[...artifacts],use_workflow_metadata:useWorkflowMetadata,metadata:{...upload,tags:splitTags(upload.tags),made_for_kids:upload.made_for_kids==='yes'}});artifacts=new Set();await load();emit('uploaded');})">{{useWorkflowMetadata?'按上方逐项管线设置上传':'以'+labels[upload.privacy]+'上传'}} {{artifacts.size}} 个成品</button>
<div class="info-note upload-task-link"><span>{{state.uploads?.length??0}} 条上传任务记录</span><button class="subtle" @click="$emit('navigate','/tasks/all')">查看任务中心 ↗</button></div></section>
<section v-if="page==='videos'" class="panel yt-section"><div class="yt-row"><h2>频道视频 · {{state.videos.length}}</h2><button class="subtle" :disabled="busy||!state.connected" @click="run(async()=>{await api('/sync',{});await load();})">同步全部频道视频</button></div><p v-if="state.last_sync" class="muted">最近同步 {{new Date(state.last_sync.completed_at).toLocaleString('zh-CN')}} · {{state.last_sync.count}} 个唯一视频 · {{state.last_sync.records}} 条列表记录 · 已过滤 {{state.last_sync.duplicates}} 条重复记录</p><div class="yt-row"><input v-model="search" aria-label="搜索频道视频" placeholder="搜索标题 / 视频 ID"/><select v-model="privacyFilter" aria-label="筛选视频公开状态"><option value="">全部公开状态</option><option value="private">私密</option><option value="unlisted">不公开</option><option value="public">公开</option></select><select v-model="groupFilter" aria-label="筛选视频本地分组"><option value="">全部本地分组</option><option v-for="g in groups" :key="g">{{g}}</option></select><button class="subtle" @click="selectAll">全选筛选结果</button><button class="subtle" @click="selectPage">选本页</button><button class="subtle" @click="invertResults">反选筛选结果</button><button class="subtle" :disabled="!videos.size" @click="clearSelection">取消全部选择</button></div><div class="yt-scroll"><table><thead><tr><th></th><th>视频标题</th><th>公开状态</th><th>本地分组</th><th>处理状态</th></tr></thead><tbody><tr v-for="v in visible" :key="v.id"><td><input type="checkbox" :checked="videos.has(v.id)" :aria-label="'选择视频 '+v.snippet.title" @click="toggleVideo(v.id,$event)"/></td><td><a :href="'https://www.youtube.com/watch?v='+encodeURIComponent(v.id)" target="_blank" rel="noreferrer">{{v.snippet.title}}</a><small class="block muted">{{v.id}}</small></td><td>{{labels[v.status.privacyStatus]}}</td><td>{{v.local_group||'未分组'}}</td><td>{{v.status.uploadStatus}}</td></tr></tbody></table></div><p v-if="!state.videos.length" class="muted">连接账号后点击同步，读取频道上传列表（包含自己可管理的私密视频）。</p>
<div class="table-footer"><span>筛选结果 {{filtered.length}} 个 · 每页 30 个</span><div class="pager"><button :disabled="currentPage<=1" aria-label="上一页视频" @click="pageNumber=currentPage-1">‹</button><span>{{currentPage}} / {{pages}}</span><button :disabled="currentPage>=pages" aria-label="下一页视频" @click="pageNumber=currentPage+1">›</button></div></div>
<SelectionToolbar v-bind="selection" scope="频道视频" @clear="clearSelection"><button class="subtle" @click="emit('workflow',[...videos])">加入自定义管线</button><button class="primary" :disabled="busy||!state.connected||!enabled" @click="editOpen=true">编辑选中视频</button></SelectionToolbar>
</section>
<section v-if="page==='history'" class="panel yt-section"><h2>批量变更记录 · {{state.batches.length}}</h2><p v-if="!state.batches.length">暂无批量操作。频道视频页生成的预览与执行结果会保存在这里。</p><article v-for="b in state.batches" :key="b.id" class="yt-job"><div class="yt-row"><strong>{{new Date(b.created_at).toLocaleString('zh-CN')}}</strong><span>{{b.changes.length}} 项变更</span><button class="subtle" @click="historyPreview=b">查看记录 {{b.id.slice(0,8)}}</button></div><p>{{b.changes.filter((c:any)=>c.status==='completed').length}} 项已完成 · {{b.changes.filter((c:any)=>c.status==='failed').length}} 项失败 · {{b.changes.filter((c:any)=>c.status==='pending').length}} 项待应用</p></article></section>
<div v-if="editOpen&&page==='videos'" class="modal-backdrop" @click.self="editOpen=false"><section class="modal yt-editor" role="dialog" aria-modal="true" aria-label="批量编辑频道视频"><div class="modal-heading"><h2>编辑选中视频</h2><button class="icon-button" aria-label="关闭批量编辑" @click="editOpen=false"><X :size="20"/></button></div><div v-if="error" class="warning-panel" role="alert">{{error}}</div>
<h3>批量修改 {{videos.size}} 个视频</h3><div class="yt-form"><label class="field-label">标题前缀<input v-model="edit.prefix"/></label><label class="field-label">标题查找<input v-model="edit.find"/></label><label class="field-label">替换为<input v-model="edit.replace"/></label><label class="field-label">公开状态<select v-model="edit.privacy"><option value="">保持原值</option><option value="private">私密</option><option value="unlisted">不公开</option><option value="public">公开</option></select></label></div><label class="checkbox-label"><input type="checkbox" v-model="edit.regex"/>查找使用正则表达式，捕获组替换用 $1</label><div class="yt-form"><label class="field-label"><span><input type="checkbox" v-model="changeTags"/> 替换标签</span><input v-model="edit.tags" :disabled="!changeTags" placeholder="逗号分隔；勾选后留空会清空"/></label><label class="field-label"><span><input type="checkbox" v-model="changeGroup"/> 本地分组</span><input v-model="edit.group" :disabled="!changeGroup" placeholder="应用内分组，不创建 YouTube 播放列表"/></label></div><label class="field-label"><span><input type="checkbox" v-model="changeDescription"/> 替换描述（勾选后留空会清空）</span><textarea v-model="edit.description" :disabled="!changeDescription" rows="3"/></label><button class="subtle" :disabled="busy||!videos.size||!state.connected" @click="makePreview">预览修改</button>
<div v-if="preview" class="yt-preview"><h3>预览 · 确认后写入 YouTube</h3><article v-for="c in preview.changes" :key="c.id"><strong>{{c.before.snippet.title}}</strong><p v-if="c.after.snippet">新标题：{{c.after.snippet.title}}<br/>新描述：{{c.after.snippet.description}}<br/>新标签：{{c.after.snippet.tags?.join(', ')}}</p><p v-if="c.after.status">公开状态：{{labels[c.before.status.privacyStatus]}} → {{labels[c.after.status.privacyStatus]}}</p><p v-if="c.after.local_group!==undefined">本地分组：{{c.after.local_group||'清空'}}</p><small>{{labels[c.status]}} {{c.message}}</small></article><button class="primary" :disabled="busy||!preview.changes.some((c:any)=>c.status==='pending')" @click="run(async()=>{preview=await api(`/batches/${preview.id}/apply`,{});await load();})">确认应用 {{preview.changes.length}} 项修改</button></div>

</section></div>
<div v-if="historyPreview&&page==='history'" class="modal-backdrop" @click.self="historyPreview=null"><section class="modal yt-editor" role="dialog" aria-modal="true" aria-label="批量操作记录"><div class="modal-heading"><h2>变更记录</h2><button class="icon-button" aria-label="关闭记录" @click="historyPreview=null"><X :size="20"/></button></div><article v-for="c in historyPreview.changes" :key="c.id" class="yt-job"><strong>{{c.before.snippet.title}}</strong><p v-if="c.after.snippet">新标题：{{c.after.snippet.title}}<br/>新描述：{{c.after.snippet.description}}<br/>新标签：{{c.after.snippet.tags?.join(', ')}}</p><p v-if="c.after.status">公开状态：{{labels[c.after.status.privacyStatus]}}</p><p v-if="c.after.local_group!==undefined">本地分组：{{c.after.local_group||'清空'}}</p><small>{{labels[c.status]??c.status}} {{c.message}}</small></article><button v-if="historyPreview.changes.some((c:any)=>c.status==='pending')" class="primary" :disabled="busy||!state.connected||!enabled" @click="run(async()=>{historyPreview=await api('/batches/'+historyPreview.id+'/apply',{});await load();})">确认应用待执行变更</button></section></div>

</template>
</div>
</template>
<style scoped>
.yt-editor{width:850px}.yt-editor h3{margin-bottom:16px}.yt-editor textarea{width:100%;border:1px solid var(--border);border-radius:8px;padding:10px;font:inherit}.upload-task-link{align-items:center;justify-content:space-between;margin-top:20px}.yt-scroll table td:nth-child(2){white-space:normal;min-width:240px;max-width:640px;overflow-wrap:anywhere}.yt-scroll table{font-size:12px}.yt-section .yt-scroll{max-height:60vh}
.yt-section{padding:24px;margin-bottom:22px}.yt-row{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:12px 0}.yt-row h2{margin-right:auto}.yt-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px}.yt-scroll{max-height:420px;overflow:auto;margin:16px 0}.yt-job{padding:14px 0;border-top:1px solid var(--border);margin-top:14px}.yt-job progress{width:100%}.yt-section textarea{width:100%;border:1px solid var(--border);border-radius:8px;padding:10px;font:inherit}.yt-section input:not([type=checkbox]):not([type=file]),.yt-section select{min-width:140px;max-width:100%;padding:10px;border:1px solid var(--border);border-radius:8px}.yt-preview{margin-top:20px;padding:18px;background:var(--surface-soft);border:1px solid var(--border);border-radius:12px}.yt-preview article{padding:12px 0;border-bottom:1px solid var(--border);overflow-wrap:anywhere}.yt-section p{line-height:1.65}.yt-section a{color:var(--accent)}.yt-section input[type=file]{max-width:240px}table{width:100%}
</style>
